alter table public.note_folders add column if not exists parent_id uuid references public.note_folders(id) on delete set null; create index if not exists note_folders_parent on public.note_folders (parent_id); drop index if exists public.note_folders_owner_name; create unique index if not exists note_folders_owner_parent_name on public.note_folders ( owner_id, coalesce(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(btrim(name)) ); create or replace function public.check_note_folder_depth() returns trigger language plpgsql security definer set search_path = public as $$ declare parent_owner uuid; parent_parent uuid; has_children boolean; begin if new.parent_id is null then return new; end if; if new.parent_id = new.id then raise exception 'A folder cannot be inside itself.'; end if; select owner_id, parent_id into parent_owner, parent_parent from public.note_folders where id = new.parent_id; if parent_owner is null then raise exception 'That folder does not exist.'; end if; if parent_owner <> new.owner_id then raise exception 'A folder can only sit inside one of your own folders.'; end if; if parent_parent is not null then raise exception 'Folders go two levels deep: a folder, and folders inside it.'; end if; select exists (select 1 from public.note_folders where parent_id = new.id) into has_children; if has_children then raise exception 'That folder has folders inside it, so it cannot go inside another.'; end if; return new; end; $$; drop trigger if exists note_folders_depth on public.note_folders; create trigger note_folders_depth before insert or update of parent_id on public.note_folders for each row execute procedure public.check_note_folder_depth(); alter table public.note_folders add column if not exists color text check (color is null or color in ('red','orange','gold','green','teal','blue','purple','pink')); alter table public.notes add column if not exists color text check (color is null or color in ('red','orange','gold','green','teal','blue','purple','pink')); alter table public.notes add column if not exists body_format text not null default 'plain' check (body_format in ('plain','html'));
